const statsGroups=[
 ['statsRounds',[['statsJan','january_count'],['statsApr','april_count']]],
 ['statsGroups',[['statsUniversity','university_count'],['statsCommunity','community_count']]],
 ['statsProvinces',[['statsBagmati','bagmati_count'],['statsGandaki','gandaki_count']]],
 ['statsWorkflow',[['statsDemo','demo_count'],['statsQualifiers','qualifier_count'],['statsFinalists','finalist_count'],
 ['statsMockFee','mock_fee_count'],['statsScores','score_count'],['statsVotes','vote_count'],['statsVouchers','voucher_count']]]
];
function validStatistics(){
 const p=state?.statistics;
 return state?.actor?.role==='organizer'&&p?.scope==='single_synthetic_workspace_only'&&
 p?.workspace_id===state.actor.workspace_id&&p?.stats?p:null;
}
function renderStatistics(){
 const container=$('stats-summary'),detail=$('stats-breakdown'),updated=$('stats-updated');
 container.replaceChildren();detail.replaceChildren();updated.replaceChildren();
 const proof=validStatistics();
 if(!proof){container.append(node('p',tr('statsUnavailable')));return}
 const counts=proof.stats;
 for(const [label,key] of [['statsApplicants','applicant_count'],['statsApplications','application_count'],
 ['statsDemo','demo_count'],['statsFinalists','finalist_count']]){
  const card=node('div',undefined,'stats-kpi');
  card.append(node('span',tr(label)),node('strong',Number(counts[key]||0)));container.append(card);
 }
 const asOf=new Date(proof.as_of);
 updated.textContent=tr('statsUpdated')+' · '+
  (Number.isNaN(asOf.getTime())?'—':asOf.toLocaleString(language==='zh'?'zh-TW':language==='ne'?'ne-NP':'en-US',
   {timeZone:'Asia/Kathmandu',year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}))+' (Nepal)';
 for(const [name,keys] of statsGroups){
  const section=node('section',undefined,'stats-group'),list=node('dl');
  section.append(node('h3',tr(name)));
  for(const [label,key] of keys){const line=node('div',undefined,'stats-line');
   line.append(node('dt',tr(label)),node('dd',Number(counts[key]||0)));list.append(line)}
  section.append(list);detail.append(section)
 }
}
function exportStatistics(){
 const p=validStatistics();if(!p){status('statsUnavailable',true);return}
 const pairs=[['scope','single_synthetic_workspace_only'],['source','cloudflare-d1-private-practice'],
 ['as_of_utc',p.as_of],...([['statsApplicants','applicant_count'],['statsApplications','application_count'],
 ...statsGroups.flatMap(g=>g[1])]).map(([label,key])=>[tr(label),String(Number(p.stats[key]||0))])];
 const csv='\uFEFF'+pairs.map(row=>row.map(s=>'"'+String(s).replaceAll('"','""')+'"').join(',')).join('\r\n');
 const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
 const a=node('a');a.href=url;a.download='ghv-test-statistics-'+p.as_of.slice(0,10)+'.csv';
 document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);
}


function renderRoleCheckpoints(){
 for(const key of ['member','judge','organizer']){$(key+'-view').dataset.complete='false'}
 if(!state)return;
 const format=(key,values={})=>tr(key).replace(/\{(count|id|entries|scores)\}/g,(_,part)=>String(values[part]??''));
 const role=state.actor.role;
 if(role==='member'){
  const count=state.applications.length,last=state.applications.at(-1);
  $('member-checkpoint').textContent=count?format('memberHas',{count,id:last.id}):tr('memberPending');
  $('member-view').dataset.complete=String(count>0);
 }else if(role==='judge'){
  const count=state.scores.length;
  $('judge-checkpoint').textContent=count?format('judgeHas',{count}):tr('judgePending');
  $('judge-view').dataset.complete=String(count>0);
 }else if(role==='organizer'){
  const entries=state.applications.length,scores=state.scores.length;
  $('organizer-checkpoint').textContent=entries?format('ownerHas',{entries,scores}):tr('ownerPending');
  $('organizer-view').dataset.complete=String(entries>0);
 }
}
