const formField=key=>({'synthetic':$('application-ack'),'priority_ack':$('priority-ack'),'media_ack':$('media-ack')}[key]||$('application-form').elements.namedItem(key));
function clearFieldErrors(){applicationError=null;for(const input of $('application-form').querySelectorAll('[aria-invalid]')){input.removeAttribute('aria-invalid');const ids=(input.getAttribute('aria-describedby')||'').split(' ').filter(id=>id&&!id.startsWith('error-'));if(ids.length)input.setAttribute('aria-describedby',ids.join(' '));else input.removeAttribute('aria-describedby')}for(const el of $('application-form').querySelectorAll('.field-error'))el.remove();$('application-feedback').replaceChildren();$('application-feedback').hidden=true;}
