$('logout').onclick=()=>action(async()=>{await api('logout',{});clearPortal();$('application-form').reset();$('score-form').reset();status('signedOut')});
$('refresh').onclick=()=>action(async()=>{await load();status('saved')});
$('application-form').onsubmit=e=>{e.preventDefault();if(pending||submission&&!submission.verified)return;const values=Object.fromEntries(new FormData($('application-form'))),payload={...values,synthetic:$('application-ack').checked,priority_ack:$('priority-ack').checked,media_ack:$('media-ack').checked},errors=validatePracticeApplication(payload);clearFieldErrors();if(Object.keys(errors).length){showApplicationErrors(errors);return}action(()=>submitApplication(payload))};
$('score-app').onchange=scoreInputs;
$('score-form').onsubmit=e=>{e.preventDefault();action(async()=>{const values=Object.fromEntries(new FormData($('score-form')));for(const key of ['technique','interpretation','stage_presence','appearance'])if(values[key]!==undefined)values[key]=Number(values[key]);await api('score',{...values,application_id:selectedApp,phase:scorePhase,no_conflict:$('no-conflict').checked,recused:$('recuse').checked,reason:$('recusal-reason').value});await load();status('scoreSaved')})};
$('cleanup-form').onsubmit=e=>{e.preventDefault();action(async()=>{await api('cleanup',{confirmation:$('cleanup-confirm').value});clearPortal();$('application-form').reset();$('score-form').reset();$('cleanup-form').reset();status('cleanupDone')})};
for(const form of document.querySelectorAll('form:not(#application-form)'))form.addEventListener('invalid',()=>status('fieldRequired',true),true);
for(const b of document.querySelectorAll('[data-lang]'))b.onclick=()=>{if(pending)return;language=b.dataset.lang;try{localStorage.setItem('ghv_ui_language_v1',language)}catch{}translate()};
translate();
await action(async()=>{try{await load();status('saved')}catch(e){if(e.code==='practice_login_required'){try{await api('readiness');status('ready')}catch(error){status(errorKey(error.code),true)}}else status(errorKey(e.code),true)}})
